 void Stop(const FString& Error){const auto Keep=AsShared();if(auto* W=World.Get())W->GetTimerManager().ClearTimer(Timer);Algo::Sort(Times);auto* S=Sprayer.Get();const double Seconds=MeasureAt>0?FPlatformTime::Seconds()-MeasureAt:0;const uint64 Frames=GFrameCounter-BaseFrame;const uint64 Samples=S?S->UpdateSamples-BaseSamples:0;const double Mean=S&&Samples?(S->TotalUpdateMs-BaseCpu)/Samples:0;const double P95=Times.IsEmpty()?0:Times[FMath::Clamp(FMath::CeilToInt(Times.Num()*.95)-1,0,Times.Num()-1)];const FString Report=FString::Printf(TEXT("valid=%d error=%s pose_change_cm=%.6f conservation_error=%.12f actor_mean_ms=%.6f actor_p95_ms=%.6f sampled_frames=%d actor_samples=%llu engine_frames=%llu wall_seconds=%.6f engine_frame_mean_ms=%.6f\n%s\n"),Error.IsEmpty(),*Error,PoseChange,S?S->ConservationError():0,Mean,P95,Times.Num(),Samples,Frames,Seconds,Frames?1000*Seconds/Frames:0,S?*S->Statistics():TEXT("no sprayer"));FString PairedReport;if(S&&Error.IsEmpty()){const double Before=S->RemainingVolume();const FVector2D Pair=S->MeasureCoatingPair();PairedReport=FString::Printf(TEXT("held_coating_serial_ms=%.6f held_coating_parallel_ms=%.6f held_coating_mass_delta=%.12f\n"),Pair.X,Pair.Y,S->RemainingVolume()-Before);const FVector SurfacePair=S->MeasureSurfaceQueryPair();PairedReport+=FString::Printf(TEXT("held_mask_previous_ms=%.6f held_mask_reused_ms=%.6f held_mask_max_difference=%.12g held_mask_mass_delta=%.12f\n"),SurfacePair.X,SurfacePair.Y,SurfacePair.Z,S->RemainingVolume()-Before);const FVector SweepPair=S->MeasureSweepPair();PairedReport+=FString::Printf(TEXT("held_sweep_previous_ms=%.6f held_sweep_cached_ms=%.6f held_sweep_mismatches=%.0f\n"),SweepPair.X,SweepPair.Y,SweepPair.Z);const FVector2D BufferPair=S->MeasureBufferPair();PairedReport+=FString::Printf(TEXT("held_buffer_rebuild_ms=%.6f held_buffer_reuse_ms=%.6f held_buffer_mass_delta=%.12f\n"),BufferPair.X,BufferPair.Y,S->RemainingVolume()-Before);}
 FFileHelper::SaveStringToFile(SprayReport+Report+PairedReport,*(Output/TEXT("report.txt")));UE_LOG(LogTemp,Display,TEXT("Paint performance audit %s"),*Report);FPlatformMisc::RequestExitWithStatus(false,Error.IsEmpty()?0:1);}
